begin;
select no_plan();
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f' and position('''40001''' in p.prosrc)>0),0::bigint,'business conflicts cannot trigger PostgREST serialization retry loops');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select set_config('test.chat',public.create_conversation('00000000-0000-4000-8000-000000000101','Original paged conversation')::text,true);
select public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.chat')::uuid,'00000000-0000-4000-8000-000000000601','First original question');
select public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.chat')::uuid,'00000000-0000-4000-8000-000000000601','Second original question');
select is((select string_agg(role,',' order by message_index) from public.chat_messages),'user,assistant,user,assistant','transaction-equal timestamps retain deterministic message order');
select throws_ok($$select public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.chat')::uuid,'00000000-0000-4000-8000-000000000601','Schedule this unapproved draft','schedule')$$,'23514',null,'GROS rejects a scheduling proposal without a ready exact package');
select throws_ok($$select public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.chat')::uuid,'00000000-0000-4000-8000-000000000601','Assign this unapproved copy','request_assignment')$$,'23514',null,'assignment proposal requires actual owner-approved copy');
select set_config('test.r',public.reserve_fixture_usage('00000000-0000-4000-8000-000000000101','original-stale-manual-reservation','learning',1000)::text,true);
update public.usage_reservations set expires_at=now()-interval '1 second' where id=current_setting('test.r')::uuid;
select is(public.recover_expired_usage('00000000-0000-4000-8000-000000000101'),1,'stale unused manual reservation is safely released');
select is((select reserved_micro from public.package_cycles where tenant_id='00000000-0000-4000-8000-000000000101'),0::bigint,'recovery restores atomic available allowance');
select is(public.recover_expired_usage('00000000-0000-4000-8000-000000000101'),0,'reservation recovery replay is idempotent');
insert into public.job_runs(id,tenant_id,kind,idempotency_key,input,created_by,status,lease_token,lease_until) values('00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000101','ops.health','original-active-lease','{}','00000000-0000-4000-8000-000000000001','running',gen_random_uuid(),now()+interval '1 hour');
select set_config('test.r',public.reserve_fixture_usage('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000991','learning',1000)::text,true);
update public.usage_reservations set expires_at=now()-interval '1 second' where id=current_setting('test.r')::uuid;
select is(public.recover_expired_usage('00000000-0000-4000-8000-000000000101'),0,'active lease protects an expired usage hold from premature release');
update public.job_runs set lease_until=now()-interval '1 second' where id='00000000-0000-4000-8000-000000000991';
select is(public.recover_expired_usage('00000000-0000-4000-8000-000000000101'),1,'expired lease permits abandoned fixture usage recovery');
select public.add_holiday('00000000-0000-4000-8000-000000000101','Original workspace studio day',(now()+interval '2 days')::date,'Owner-supplied original event');
select is(jsonb_array_length(private.planning_holidays('00000000-0000-4000-8000-000000000101',now()+interval '1 day')),1,'custom events enter bounded plan input provenance');
select is(jsonb_array_length(private.planning_holidays('00000000-0000-4000-8000-000000000102',now()+interval '1 day')),0,'holiday lineage never leaks another tenant');
insert into public.job_runs(id,tenant_id,kind,idempotency_key,input,created_by,status,lease_token,lease_until) values('00000000-0000-4000-8000-000000000992','00000000-0000-4000-8000-000000000101','calendar.plan','original-stale-holiday-plan',jsonb_build_object('startsAt',now()+interval '1 day'),'00000000-0000-4000-8000-000000000001','running','00000000-0000-4000-8000-000000000993',now()+interval '1 hour');
select is(jsonb_array_length((select input->'holidays' from public.job_runs where id='00000000-0000-4000-8000-000000000992')),1,'enqueue freezes exact custom-event inputs before generation');
select public.add_holiday('00000000-0000-4000-8000-000000000101','Another original workspace day',(now()+interval '3 days')::date,'Changed after generation began');
select throws_ok($$select public.finish_plan_job('00000000-0000-4000-8000-000000000992','00000000-0000-4000-8000-000000000993','{"synthetic":true,"entries":[]}'::jsonb)$$,'PT409','Workspace events or pinned learning changed','event changes reject stale generated output before any campaign mutation');
select set_config('request.jwt.claim.role','service_role',true);
update public.tenants set status='paused' where id='00000000-0000-4000-8000-000000000101';
select throws_ok($$select public.claim_job('00000000-0000-4000-8000-000000000101')$$,'42501',null,'service worker cannot dispatch a paused workspace');
update public.tenants set status='active' where id='00000000-0000-4000-8000-000000000101';
select set_config('request.jwt.claim.role','authenticated',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select throws_ok($$select public.recover_expired_usage('00000000-0000-4000-8000-000000000101')$$,'42501',null,'staff cannot manipulate allowance recovery');
select * from finish();rollback;
